import re,pathlib
# collect local declarations in functions and compare simple arr + int occurrences
for p in pathlib.Path('src').rglob('*.c'):
 s=p.read_text(errors='ignore')
 macros=dict((m.group(1), int(m.group(2))) for m in re.finditer(r'#define\s+(\w+)\s+(\d+)', s))
 for m in re.finditer(r'struct\s+sc_asn1_entry\s+([^;]*);', s):
  decl=m.group(1)
  arrays={}
  for a,sz in re.findall(r'(\w+)\s*\[([^\]]+)\]', decl):
   n=None
   if sz.isdigit(): n=int(sz)
   elif sz in macros: n=macros[sz]
   if n: arrays[a]=n
  if not arrays: continue
  # scan next 150 lines until maybe function end hard no
  start=m.end(); sub=s[start:start+6000]
  for arr,n in arrays.items():
   for fm in re.finditer(r'sc_format_asn1_entry\(\s*'+re.escape(arr)+r'\s*\+\s*(\d+)', sub):
    idx=int(fm.group(1))
    if idx>=n:
     line=s.count('\n',0,start+fm.start())+1
     print('FORMAT OOB',p,line,arr,n,'+',idx)
   for fm in re.finditer(r'&'+re.escape(arr)+r'\s*\[\s*(\d+)\s*\]', sub):
    idx=int(fm.group(1))
    if idx>=n:
     line=s.count('\n',0,start+fm.start())+1
     print('INDEX OOB',p,line,arr,n,'[',idx,']')
